'''KV Cache 显存估算：MHA / GQA / MQA / MLA 与 KV 量化。

公式主线（MHA/GQA/MQA）：bytes = 2 * L * H_kv * d_head * S * B * BPE
其中 2 是 K 与 V 两份；MLA 把 2 * H_kv * d_head 换成 d_c + d_rope
（压缩潜向量 + 解耦的 RoPE 分量）；BPE 是每元素字节数，由位宽与量化分组决定。
运行：python kv_cache_calc.py   只依赖标准库，模型参数都是可替换的示例量级。
'''

GIB = 1024 * 1024 * 1024


class AttnConfig:
    '''一种注意力结构的 KV 缓存形状：非 MLA 用 kv_heads * d_head，MLA 用潜维。'''

    def __init__(self, name, layers, kv_heads=None, head_dim=None,
                 latent_dim=0, rope_dim=0, heads=None):
        if layers <= 0:
            raise ValueError('layers 必须为正，实际 %r' % (layers,))
        if latent_dim > 0:
            if rope_dim < 0:
                raise ValueError('rope_dim 不能为负')
        elif not (kv_heads and head_dim):
            raise ValueError('非 MLA 结构必须同时给出 kv_heads 与 head_dim')
        self.name, self.layers = name, layers
        self.kv_heads, self.head_dim = kv_heads, head_dim
        self.latent_dim, self.rope_dim = latent_dim, rope_dim
        self.heads = heads

    @property
    def is_mla(self):
        return self.latent_dim > 0

    def elements_per_token(self):
        '''每 token 每层缓存多少元素（与精度无关，是估算的不变量）。'''
        if self.is_mla:
            return self.latent_dim + self.rope_dim
        return 2 * self.kv_heads * self.head_dim

    def describe(self):
        if self.is_mla:
            return 'MLA d_c=%d + d_rope=%d' % (self.latent_dim, self.rope_dim)
        kind = 'MHA' if self.heads and self.kv_heads == self.heads else 'GQA/MQA'
        return '%s H_kv=%d d_head=%d' % (kind, self.kv_heads, self.head_dim)


def bytes_per_element(bits, group_size=0, scale_bytes=2):
    '''BPE = bits / 8 + scale_bytes / group_size；group_size=0 表示无分组也无 scale。'''
    if bits <= 0:
        raise ValueError('bits 必须为正')
    if group_size < 0 or scale_bytes < 0:
        raise ValueError('group_size / scale_bytes 不能为负')
    bpe = bits / 8.0
    if group_size:
        bpe += scale_bytes / group_size
    return bpe


def kv_cache_bytes(cfg, seq_len, batch=1, bits=16, group_size=0):
    '''整段 KV 缓存字节数；seq_len 或 batch 为 0 时返回 0.0。'''
    if seq_len < 0 or batch < 0:
        raise ValueError('seq_len / batch 不能为负')
    if seq_len == 0 or batch == 0:
        return 0.0
    per_token = cfg.layers * cfg.elements_per_token() * bytes_per_element(bits, group_size)
    return per_token * seq_len * batch


def max_sequences(cfg, seq_len, budget_bytes, bits=16, group_size=0):
    '''显存预算内能同时驻留几条该长度的序列（向下取整）。'''
    one = kv_cache_bytes(cfg, seq_len, bits=bits, group_size=group_size)
    if one <= 0:
        raise ValueError('单序列占用为 0，无法估算并发数')
    return int(budget_bytes // one)


def human(n):
    for unit in ('B', 'KiB', 'MiB'):
        if abs(n) < 1024:
            return '%.2f %s' % (n, unit)
        n /= 1024.0
    return '%.2f GiB' % n


def main():
    seq = 4096
    mha = AttnConfig('MHA 基线', layers=60, kv_heads=128, head_dim=128, heads=128)
    gqa = AttnConfig('GQA 8 组', layers=60, kv_heads=8, head_dim=128, heads=128)
    mqa = AttnConfig('MQA 单组', layers=60, kv_heads=1, head_dim=128, heads=128)
    mla = AttnConfig('MLA 潜向量', layers=60, latent_dim=512, rope_dim=64)

    print('每 token 每层元素数：MHA=%d GQA=%d MQA=%d MLA=%d' % (
        mha.elements_per_token(), gqa.elements_per_token(),
        mqa.elements_per_token(), mla.elements_per_token()))
    for cfg in (mha, gqa, mqa, mla):
        print('%-10s %-22s 每 token %10s | S=%d 单序列 %10s' % (
            cfg.name, cfg.describe(), human(kv_cache_bytes(cfg, 1)),
            seq, human(kv_cache_bytes(cfg, seq))))

    ratio = kv_cache_bytes(mha, 1) / kv_cache_bytes(mla, 1)
    print('MLA 相对同层数同头数 MHA：%.2f 倍压缩，降 %.1f%%' % (ratio, 100 * (1 - 1 / ratio)))

    for bits, group in ((16, 0), (8, 0), (4, 64), (4, 128)):
        print('量化 bits=%2d group=%3d -> BPE=%.5f | MLA 每 token %s' % (
            bits, group, bytes_per_element(bits, group),
            human(kv_cache_bytes(mla, 1, bits=bits, group_size=group))))

    v3 = AttnConfig('V3 量级', layers=61, latent_dim=512, rope_dim=64)
    ctx = 131072
    print('61 层 MLA、S=%d：每 token %s，单序列 %s' % (
        ctx, human(kv_cache_bytes(v3, 1)), human(kv_cache_bytes(v3, ctx))))
    print('40 GiB 预算下并发 128K 序列数：%d' % max_sequences(v3, ctx, 40 * GIB))

    assert mha.elements_per_token() == 2 * 128 * 128 == 32768
    assert gqa.elements_per_token() == 2 * 8 * 128
    assert mla.elements_per_token() == 512 + 64
    assert kv_cache_bytes(mha, 1) == 2 * 128 * 128 * 60 * 2
    assert kv_cache_bytes(mla, 1) == (512 + 64) * 60 * 2
    assert abs(ratio - 512 / 9) < 1e-9
    assert bytes_per_element(4, 64) == 0.5 + 2 / 64
    assert bytes_per_element(4, 128) < bytes_per_element(4, 64)
    assert kv_cache_bytes(gqa, seq, bits=8) == kv_cache_bytes(gqa, seq, bits=16) / 2
    assert kv_cache_bytes(mla, 0) == 0.0 and kv_cache_bytes(mla, 10, batch=0) == 0.0
    assert max_sequences(v3, ctx, 40 * GIB) == 4
    print('all assertions passed')


if __name__ == '__main__':
    main()
